__li__FB __string_176={__li__FB__,{815,"void print_integer(int64_t n)        \
   \n{ int64_t val;                       \n  char car;                     \
     \n  if (n<0) { print_char('-'); n=-n;};\n  car = (n % 10) + '0';       \
       \n  val = n / 10;                      \n  if (val != 0) print_intege\
r(val);  \n  print_char(car);                   \n} \n\nvoid print_integer_h\
_2(uint64_t n,int64_t l) \n{ uint64_t val,v,j;            \n  char car;     \
                      \n  v = n & 0xF;                        \n  if (v < 10\
) car = v + '0'; else car = (v-10) + 'A'; \n  val = n >> 4;                 \
      \n  if (val != 0) print_integer_h_2(val,l-1); else \n  for (j=0;j<l;j+\
+) print_string(\"-\"); \n  print_char(car);                    \n} \n \nvoi\
d print_integer_h(uint64_t n)  \n{                                      \n  \
print_integer_h_2(n,15);             \n} \n \n\n"},867167136};
